  int bestHeight = readings[0];
  for (int height in readings) {
    int bestPrev = 0;
    for (int prevHeight in [height - 1, height, height + 1]) {
      if (dp.containsKey(prevHeight)) {
        int val = dp[prevHeight]!;
        if (val > bestPrev) bestPrev = val;
